// Disclaimer Text is versioned with the tax parameter set (ADR-0002), so it tracks the law year; es-MX, safe to show, never an amount. Order in a response: `not_tax_advice` first, then by severity (`strong`, `warning`, `info`), then by code.
//
// Examples: {"code":"not_tax_advice","severity":"info","text":"Estimación informativa. No sustituye la declaración ante el SAT ni la asesoría de un contador. Cálculo basado en LISR, LIVA, LIF 2026 y Anexo 8 RMF 2026."}
type Disclaimer struct {
	// Code Append-only (like `ErrorCode`): clients show the `text` of a code they do not know. `not_tax_advice` always; `incomplete_inputs` when a regime is `incomplete`; `provisional_parameters` when the period's fiscal year has no published parameters yet; `informational_regime` / `partial_regime` when a regime has that status; `deductibility_claimed` when a deductible expense entered the ISR base; `no_coefficient_first_year` for a 601 in its first fiscal year; `iva_mixed_activity` when a regime's creditable IVA was taken in full although it has exempt acts (`iva_fully_taxable = false`, or exempt collections in the month; LIVA 5 fr. V); `cpa_review_pending` when a line applies a rule a CPA has not validated; `resico_cap_exceeded` when a RESICO (626) regime's income collected in the year is above its cap (PF 3,500,000, LISR 113-E; PM 35,000,000, LISR 206): the taxpayer leaves RESICO (PF from the next month, LISR 113-E/113-I; PM from the next fiscal year, LISR 214), the month is still estimated under RESICO (MODULE-tax-engine §2.3, §2.9). Annual estimate (MODULE-annual §2.8, 0.11.0; `annual_estimate` is first there instead of `not_tax_advice`, and `incomplete_inputs` / `cpa_review_pending` are reused): `annual_estimate` always; `year_in_progress` (current fiscal year); `payments_estimated` (a provisional payment taken from the app's estimate); `deductions_as_entered` (a personal deduction applied); `resico_pf_definitive` (a RESICO PF check section); `informative_income` (PF total income over 500,000.00, LISR 150); `rmf_2027_pending` (fiscal year 2026); `inflation_adjustment_excluded` (PM sections); `no_annual_iva` always.
	Code DisclaimerCode `json:"code"`

	// Severity `strong` is the non-dismissible amber banner above the number (`cpa_review_pending`); `warning` and `info` are shown under the estimate.
	Severity DisclaimerSeverity `json:"severity"`
	Text     string             `json:"text"`
}

// DisclaimerCode Append-only (like `ErrorCode`): clients show the `text` of a code they do not know. `not_tax_advice` always; `incomplete_inputs` when a regime is `incomplete`; `provisional_parameters` when the period's fiscal year has no published parameters yet; `informational_regime` / `partial_regime` when a regime has that status; `deductibility_claimed` when a deductible expense entered the ISR base; `no_coefficient_first_year` for a 601 in its first fiscal year; `iva_mixed_activity` when a regime's creditable IVA was taken in full although it has exempt acts (`iva_fully_taxable = false`, or exempt collections in the month; LIVA 5 fr. V); `cpa_review_pending` when a line applies a rule a CPA has not validated; `resico_cap_exceeded` when a RESICO (626) regime's income collected in the year is above its cap (PF 3,500,000, LISR 113-E; PM 35,000,000, LISR 206): the taxpayer leaves RESICO (PF from the next month, LISR 113-E/113-I; PM from the next fiscal year, LISR 214), the month is still estimated under RESICO (MODULE-tax-engine §2.3, §2.9). Annual estimate (MODULE-annual §2.8, 0.11.0; `annual_estimate` is first there instead of `not_tax_advice`, and `incomplete_inputs` / `cpa_review_pending` are reused): `annual_estimate` always; `year_in_progress` (current fiscal year); `payments_estimated` (a provisional payment taken from the app's estimate); `deductions_as_entered` (a personal deduction applied); `resico_pf_definitive` (a RESICO PF check section); `informative_income` (PF total income over 500,000.00, LISR 150); `rmf_2027_pending` (fiscal year 2026); `inflation_adjustment_excluded` (PM sections); `no_annual_iva` always.
type DisclaimerCode string

// DisclaimerSeverity `strong` is the non-dismissible amber banner above the number (`cpa_review_pending`); `warning` and `info` are shown under the estimate.
type DisclaimerSeverity string

// DocumentAcceptance Examples: {"kind":"privacy_notice_integral","version":"2026-10-01"}
type DocumentAcceptance struct {
	// Kind LFPDPPP aviso de privacidad (integral or simplificado) and términos y condiciones.
	Kind LegalDocumentKind `json:"kind"`

	// Version Opaque version label (data, not code).
	Version string `json:"version"`
}

// DoneeType `donation` only: an authorized donee (7 % cap) or a government entity (4 % within the 7 %).
type DoneeType string

// EmployerLabel Optional alias of the employer ("Empleo principal"); never an RFC or a legal name requirement. Trimmed, no control characters, stored NFC (ADR-0004); never logged.
//
// Examples: Empleo principal
type EmployerLabel = string

// EnabledFlags Examples: {"enabled":["module_auth","module_taxpayers","module_incomes","module_expenses","module_tax_engine","module_dashboard"]}
type EnabledFlags struct {
	Enabled []ModuleKey `json:"enabled"`
}

// EngineVersion Version of the tax engine that produced an estimate (`TaxpayerEstimate.engine_version`, opaque to the client). Bumped whenever an engine change can move a figure.
//
// Examples: 1.0.1
type EngineVersion = string

// ErrorCode defines model for ErrorCode.
type ErrorCode string

// ErrorResponse defines model for ErrorResponse.
type ErrorResponse struct {
	Error struct {
		Code    ErrorCode     `json:"code"`
		Details *[]FieldError `json:"details,omitempty"`

		// Message Human-readable, safe to show; never contains PII.
		Message   string `json:"message"`
		RequestId string `json:"request_id"`
	} `json:"error"`
}

// EstimateTotals Taxpayer-level totals; they carry no status (the client shows "Incompleto" when any regime is `incomplete`). `total_payable_rounded_cents = isr.payable_rounded_cents + iva.payable_rounded_cents + withholdings_to_remit_cents`.
//
// Examples: {"isr":{"amount_cents":15096,"outcome":"payable","payable_rounded_cents":15096},"iva":{"amount_cents":213333,"outcome":"payable","payable_rounded_cents":213333},"total_payable_rounded_cents":228429,"withholdings_to_remit_cents":0}
type EstimateTotals struct {
	// Isr One tax result, rounded once at the end to the centavo, half away from zero (ADR-0002 §4). `in_favor` is a saldo a favor: never shown as a payment.
	//
	// Examples: {"amount_cents":15096,"outcome":"payable","payable_rounded_cents":15096}
	Isr TaxResult `json:"isr"`

	// Iva One tax result, rounded once at the end to the centavo, half away from zero (ADR-0002 §4). `in_favor` is a saldo a favor: never shown as a payment.
	//
	// Examples: {"amount_cents":15096,"outcome":"payable","payable_rounded_cents":15096}
	Iva TaxResult `json:"iva"`

	// TotalPayableRoundedCents Amount in MXN centavos (>= 0).
	//
	// Examples: 1250000
	TotalPayableRoundedCents NonNegativeCents `json:"total_payable_rounded_cents"`

	// WithholdingsToRemitCents Amount in MXN centavos (>= 0).
	//
	// Examples: 1250000
	WithholdingsToRemitCents NonNegativeCents `json:"withholdings_to_remit_cents"`
}

// Expense `withholding` is the derived withholding (read-only, ADR-0008): all zero with `withholder: none` for a persona física taxpayer; sent for every expense written since 0.11.3 (WH-07), absent only on a legacy row until the WH-08 backfill derives it.
//
// Examples: {"amount_cents":50000,"category_code":"software","cfdi_uuid":null,"created_at":"2026-09-12T18:30:00Z","deductible":true,"deductible_source":"category_default","description":"Suscripción anual de diseño","has_cfdi":true,"id":"0199d4a3-2b3c-7e4d-9f50-6b7c8d9e0f12","isr_withheld_cents":0,"iva_cents":8000,"iva_rate":"rate_16","iva_withheld_cents":0,"legend":"Esto es un aproximado. No todos los gastos aplican para tu giro comercial.","paid_on":"2026-09-12","payment_method":"card_debit","regime_code":"612","taxpayer_id":"0199d4a2-8f00-7c44-a1b2-3c4d5e6f7a80","updated_at":"2026-09-12T18:30:00Z","warnings":[]}
type Expense struct {
	// AmountCents Amount in MXN centavos (>= 1). Same upper bound as `NonNegativeCents`.
	//
	// Examples: 1000000
	AmountCents  PositiveCents `json:"amount_cents"`
	CategoryCode string        `json:"category_code"`
	CfdiUuid     *CfdiUuid     `json:"cfdi_uuid"`
	CreatedAt    time.Time     `json:"created_at"`

	// Deductible Effective value ("the user claims it lowers ISR"): the override if any, else the default.
	Deductible bool `json:"deductible"`

	// DeductibleSource `user` when the user overrode `deductible`; `category_default` otherwise.
	DeductibleSource DeductibleSource `json:"deductible_source"`

	// Description Free text, trimmed and NFC-normalized; empty becomes `null`. Never logged (may name a client).
	Description *RecordDescription `json:"description"`
	HasCfdi     bool               `json:"has_cfdi"`

	// Id Examples: 0199d4a2-8f00-7c44-a1b2-3c4d5e6f7a80
	Id Uuid `json:"id"`

	// IsrWithheldCents Amount in MXN centavos (>= 0).
	//
	// Examples: 1250000
	IsrWithheldCents NonNegativeCents `json:"isr_withheld_cents"`

	// IvaCents Amount in MXN centavos (>= 0).
	//
	// Examples: 1250000
	IvaCents NonNegativeCents `json:"iva_cents"`

	// IvaRate rate_8 is the northern/southern border stimulus rate. Validity is date-ranged
	// tax-parameter data (in force until 2026-12-31 per DOF 31-12-2025); a rate not valid
	// on the record date is rejected with 422 business_rule_violation.
	IvaRate IvaRate `json:"iva_rate"`

	// IvaWithheldCents Amount in MXN centavos (>= 0).
	//
	// Examples: 1250000
	IvaWithheldCents NonNegativeCents `json:"iva_withheld_cents"`

	// Legend Mandatory legend; must be shown on every estimate surface.
	Legend Legend `json:"legend"`

	// OperationKind `null` for a persona física taxpayer. Always sent (nullable) since 0.11.3.
	OperationKind *OperationKind `json:"operation_kind,omitempty"`

	// PaidOn A record date on the America/Mexico_City calendar. The server refuses dates before 2026-01-01 or after today with `400 validation_failed`, `out_of_range` on that date: 2026 is the first fiscal year with a tax parameter set, so no IVA rate or withholding on an earlier date can be validated, and a record the server cannot validate is invalid input. The bounds move with the clock and the parameter catalog, so they are not schema keywords. A date outside the taxpayer's regime window answers `422 regime_not_active` first (the window is checked before the parameters). Not the same answer as the estimates: a month before 2026 there is a well-formed period the engine has no parameters for, `422 business_rule_violation` / `parameters_unavailable` (`getTaxpayerEstimate`).
	//
	// Examples: 2026-09-10
	PaidOn BusinessDate `json:"paid_on"`

	// PaymentMethod `cash` drives the cash-payment deductibility rule (`cash_over_threshold`).
	PaymentMethod PaymentMethod `json:"payment_method"`

	// RegimeCode SAT c_RegimenFiscal code.
	//
	// Examples: 612
	RegimeCode RegimeCode `json:"regime_code"`

	// ResidentialRent Always sent since 0.11.3.
	ResidentialRent *bool `json:"residential_rent,omitempty"`

	// SupplierKind `null` for a persona física taxpayer. Always sent (nullable) since 0.11.3.
	SupplierKind *SupplierKind `json:"supplier_kind,omitempty"`

	// SupplierRegime `null` unless `supplier_kind: pf_with_activity`. Always sent (nullable) since 0.11.3.
	SupplierRegime *SupplierRegime `json:"supplier_regime,omitempty"`

	// TaxpayerId Examples: 0199d4a2-8f00-7c44-a1b2-3c4d5e6f7a80
	TaxpayerId Uuid      `json:"taxpayer_id"`
	UpdatedAt  time.Time `json:"updated_at"`

	// Warnings Non-blocking notices computed on writes (create, update, restore), never stored; `[]` on reads. Codes (append-only): `cash_over_threshold` (`payment_method`), `no_cfdi` (`has_cfdi`), `not_isr_deductible_in_regime` and `category_not_deductible` (`deductible`), `duplicate_cfdi_uuid` (`cfdi_uuid`), `iva_not_creditable_cash_payment` (`payment_method`), `provisional_parameters` (`paid_on`), `deduction_requires_remittance` (`withholding`), `withholding_cpa_unverified` (`withholding`), `supplier_regime_unknown` (`supplier_regime`), `foreign_counterparty_not_supported` (`supplier_kind`).
	Warnings []Warning `json:"warnings"`

	// Withholding **Derived, never entered** (ADR-0008, MODULE-withholdings §3). The server computes it with the kernel's decision table from the facts of the record (person type and regime of the taxpayer, `counterparty_kind` or the supplier fields, `operation_kind`, `residential_rent`, `via_platform`, amounts, dates) and stores it with the `table_version` that produced it. No request accepts it. `isr_cents` and `iva_cents` are the record's `isr_withheld_cents` / `iva_withheld_cents`. Amounts: `isr_cents = round(amount_cents × isr_rate)`; `iva_cents` is the `iva_basis` share of the record's IVA, or 4 % of `amount_cents`; one rounding to the centavo, half away from zero. `net_cents` = subtotal + IVA − both withholdings: what the taxpayer receives (income) or pays the supplier (expense).
	//
	// Examples: {"cpa_unverified":false,"explanations":[{"rule_id":"ISR-4","text":"La empresa te retiene 1.25 % de ISR porque estás en RESICO (LISR art. 113-J)."},{"rule_id":"IVA-6","text":"Y 2/3 del IVA por servicios de persona física (LIVA art. 1-A, RLIVA art. 3)."}],"isr_cents":125000,"isr_rate":"0.0125","iva_basis":"two_thirds_of_iva","iva_cents":1066667,"net_cents":10408333,"remit_due_on":null,"rule_ids":["ISR-4","IVA-6"],"table_version":"2026.1","withholder":"counterparty"}
	Withholding *Withholding `json:"withholding,omitempty"`
}

// ExpenseCategory Examples: {"code":"software","deductibility":"deductible","default_deductible":true,"default_operation_kind":"business_services","legal_basis":"LISR 103","name":"Software y suscripciones","note":null}
type ExpenseCategory struct {
	Code string `json:"code"`

	// Deductibility The hint shown for a category in the taxpayer's regime (after options such as 606 `blind_35`).
	Deductibility Deductibility `json:"deductibility"`

	// DefaultDeductible The `deductible` a new expense starts with (before the CFDI and cash rules); conservative for partial cases.
	DefaultDeductible bool `json:"default_deductible"`

	// DefaultOperationKind What was sold or which service was given (MODULE-withholdings §2.1 Q2, §2.2 E3). `rent_real_estate` is the one that asks `residential_rent`; `ground_freight` is road freight of goods (IVA withheld 4 % of the price); `scrap` is desperdicios y reciclables (IVA withheld 100 %); `other` never withholds IVA. There is no subcontracting value: LIVA 1-A fr. IV (6 %) was repealed in 2021 (owner decision 4). A platform sale is not an operation kind on the wire: it is `via_platform: true`.
	//
	// Examples: professional_services
	DefaultOperationKind *OperationKind `json:"default_operation_kind,omitempty"`

	// LegalBasis Article-level basis (e.g. `LISR 103`).
	LegalBasis *string `json:"legal_basis"`

	// Name es-MX display name.
	Name string `json:"name"`

	// Note es-MX note shown with the hint.
	Note *string `json:"note"`
}

// ExpenseCategoryList Examples: {"cash_payment_limit_cents":200000,"items":[{"code":"software","deductibility":"deductible","default_deductible":true,"default_operation_kind":"business_services","legal_basis":"LISR 103","name":"Software y suscripciones","note":null},{"code":"servicios_profesionales","deductibility":"deductible","default_deductible":true,"default_operation_kind":"professional_services","legal_basis":"LISR arts. 25, 103, 115","name":"Honorarios y servicios profesionales","note":null},{"code":"combustible","deductibility":"deductible","default_deductible":true,"default_operation_kind":"business_services","legal_basis":"LISR 27","name":"Combustibles","note":"Sólo deducible si lo pagas con tarjeta, transferencia o monedero, sin importar el monto"},{"code":"restaurantes","deductibility":"partially_deductible","default_deductible":false,"default_operation_kind":"business_services","legal_basis":"LISR 28","name":"Consumo en restaurantes","note":"Sólo una parte es deducible"}],"iva_rates_allowed":["rate_16","rate_8","rate_0","exempt"],"legend":"Esto es un aproximado. No todos los gastos aplican para tu giro comercial."}
type ExpenseCategoryList struct {
	// CashPaymentLimitCents Amount in MXN centavos (>= 0).
	//
	// Examples: 1250000
	CashPaymentLimitCents NonNegativeCents  `json:"cash_payment_limit_cents"`
	Items                 []ExpenseCategory `json:"items"`
	IvaRatesAllowed       []IvaRate         `json:"iva_rates_allowed"`

	// Legend Mandatory legend; must be shown on every estimate surface.
	Legend Legend `json:"legend"`
}

// ExpenseCreate `user_id` comes from the session and `taxpayer_id` from the path, never from the body. Withholdings are **derived** (ADR-0008): a persona moral taxpayer describes its supplier (`supplier_kind`, required for it since 0.11.3; `supplier_regime`; `operation_kind`, defaulting to the category's; `residential_rent`) and the server derives what it must withhold and remit. A persona física never withholds from a domestic supplier: any supplier field answers `422` `supplier_not_applicable`. **0.11.3 (WH-07):** the deprecated `isr_withheld_cents` and `iva_withheld_cents` with any value answer `400 additionalProperties`; they leave the schema with WH-12, which regenerates the Dart client with the new form.
